import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { texture, uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new Group();
  const cleanupList = [];

  // 1. Resolve Colors and Specs
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 2. Build Backdrop Stage (Engineered Gradient Panel)
  // Dimensions fitting the spec and composition: x in [-3.5, 3.5], y in [-3, 2.5]
  const backgroundGeo = new PlaneGeometry(7.0, 5.5);
  const backgroundMat = new MeshBasicNodeMaterial({
    depthWrite: false
  });

  // Vertical gradient Node logic using three/tsl node-level functions
  const colorBottom = vec3(new Color(colors.surface));
  const colorTop = vec3(new Color(colors.ink));
  const gradientFactor = uv().y;
  backgroundMat.colorNode = mix(colorBottom, colorTop, gradientFactor);

  const backgroundMesh = new Mesh(backgroundGeo, backgroundMat);
  backgroundMesh.position.set(0, 0, -2.5); // Placed deep behind per specification
  group.add(backgroundMesh);

  // 3. Render Main Image Decal (Orb Decor Plane)
  // Explicitly mapping source rect: 0, 0, 512, 320 -> Aspect ratio 1.6:1
  const imageGeo = new PlaneGeometry(1.6 * 1.5, 1.5);
  const imageMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1.0,
    depthWrite: true
  });

  const imageMesh = new Mesh(imageGeo, imageMat);
  imageMesh.position.set(0, -0.2, 0.1);
  group.add(imageMesh);

  // Load the target texture cleanly from config
  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/orb-decor.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    // Basic mapping assignment
    imageMat.colorNode = texture(tex);
    imageMat.needsUpdate = true;
  }).catch((err) => {
    // Fail-safe color if load is blocked
    imageMat.colorNode = vec3(new Color(colors.accent));
    imageMat.needsUpdate = true;
  });

  // 4. Subtle Ambient Floating Motion (Static composition styling with slight breathing)
  const breathingTl = gsap.timeline({ repeat: -1, yoyo: true });
  breathingTl.to(imageMesh.position, {
    y: '-=0.04',
    duration: 3.5,
    ease: 'power1.inOut'
  });
  cleanupList.push(() => breathingTl.kill());

  // 5. Cleanup Handlers
  group.userData = {
    handlers: {},
    cleanup: () => {
      cleanupList.forEach((dt) => dt());
      backgroundGeo.dispose();
      backgroundMat.dispose();
      imageGeo.dispose();
      imageMat.dispose();
    }
  };

  return group;
}
